// Edge compute index — record JAH-GPC-JETSONBOARD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tops": 20, "ram_gb": 8, "price_usd": 250};
var value = (m.tops*m.ram_gb/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-JETSONBOARD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-JETSONBOARD-000001|' + value.toFixed(2) + ' edge index');

